def remove_Occ(s, char):
    first = s.find(char)
    last = s.rfind(char)
    if first == -1:
        return s
    if first == last:
        return s[:first] + s[first+1:]
    return s[:first] + s[first+1:last] + s[last+1:]

def is_woodall(n: int) -> bool:
    # A Woodall number is of the form n*2^n - 1 for some integer n >= 1
    # We need to check if given n can be expressed as k*2^k - 1 for some k
    if n < 0:
        return False
    x = n + 1
    # Try all k such that k*2^k == x
    # Since k*2^k grows fast, we can limit k to a reasonable range
    # For 64-bit integers, k up to 64 is enough
    for k in range(1, 65):
        if k * (1 << k) == x:
            return True
    return False

def binomial_Coeff(n: int, k: int) -> int:
    if k > n:
        return 0
    if k == 0 or k == n:
        return 1
    k = min(k, n - k)
    c = 1
    for i in range(k):
        c = c * (n - i) // (i + 1)
    return c

def max_Prime_Factors(n: int) -> int:
    max_prime = -1
    while n % 2 == 0:
        max_prime = 2
        n //= 2
    factor = 3
    while factor * factor <= n:
        while n % factor == 0:
            max_prime = factor
            n //= factor
        factor += 2
    if n > 2:
        max_prime = n
    return max_prime

def find_Nth_Digit(numerator: int, denominator: int, n: int) -> int:
    # Get the remainder after integer division
    remainder = numerator % denominator
    for _ in range(n - 1):
        remainder = (remainder * 10) % denominator
    return (remainder * 10) // denominator

def div_even_odd(lst):
    even = next((x for x in lst if x % 2 == 0), None)
    odd = next((x for x in lst if x % 2 != 0), None)
    if even is None or odd is None or odd == 0:
        return None
    return even / odd

from collections import Counter

def freq_element(lst):
    return dict(Counter(x for sublist in lst for x in sublist))

def counting_sort(arr):
    if not arr:
        return []
    max_val = max(arr)
    min_val = min(arr)
    range_of_elements = max_val - min_val + 1
    count = [0] * range_of_elements
    for num in arr:
        count[num - min_val] += 1
    sorted_arr = []
    for i, c in enumerate(count):
        sorted_arr.extend([i + min_val] * c)
    return sorted_arr

def max_difference(pairs: tuple) -> int:
    if not pairs:
        return 0
    values = [abs(a - b) for a, b in pairs]
    return max(values) if values else 0

def recursive_list_sum(lst):
    if not lst:
        return 0
    head, *tail = lst
    if isinstance(head, list):
        return recursive_list_sum(head) + recursive_list_sum(tail)
    return (head if isinstance(head, (int, float)) else 0) + recursive_list_sum(tail)

def bell_number(n: int) -> int:
    if n == 0:
        return 1
    bell = [0] * (n + 1)
    bell[0] = 1
    for i in range(1, n + 1):
        bell[i] = 0
        for j in range(i):
            bell[i] += bell[j] * comb(i - 1, j)
    return bell[n]

def comb(n, k):
    if k > n:
        return 0
    if k == 0 or k == n:
        return 1
    c = 1
    for i in range(min(k, n - k)):
        c = c * (n - i) // (i + 1)
    return c

def is_sublist(lst, sublst):
    if not sublst:
        return True
    n, m = len(lst), len(sublst)
    if m > n:
        return False
    for i in range(n - m + 1):
        if lst[i:i+m] == sublst:
            return True
    return False

def comb_sort(arr):
    gap = len(arr)
    shrink = 1.3
    sorted = False

    while not sorted:
        gap = int(gap / shrink)
        if gap <= 1:
            gap = 1
            sorted = True
        i = 0
        while i + gap < len(arr):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                sorted = False
            i += 1
    return arr

def count_Squares(length, width):
    total = 0
    max_side = min(length, width)
    for side in range(1, max_side + 1):
        total += (length - side + 1) * (width - side + 1)
    return total

def sequence(n):
    if n == 1 or n == 2:
        return 1
    seq = [0, 1, 1]
    for i in range(3, n + 1):
        seq.append(seq[seq[i - 1]] + seq[i - seq[i - 1]])
    return seq[n]

def is_undulating(num: int) -> bool:
    s = str(num)
    if len(s) < 3:
        return False
    for i in range(2, len(s)):
        if s[i] != s[i-2]:
            return False
    return s[0] != s[1]

