def multiply_num(lst):
    if not lst:
        return 0
    product = 1
    for num in lst:
        product *= num
    return product / len(lst)

def next_smallest_palindrome(n):
    s = str(n)
    length = len(s)
    if all(ch == '9' for ch in s):
        return n + 2  # e.g. 9 -> 11, 99 -> 101

    def is_palindrome(x):
        return x == x[::-1]

    if is_palindrome(s):
        n += 1
        s = str(n)

    half = (length + 1) // 2
    left = s[:half]
    if length % 2 == 0:
        pal_candidate = left + left[::-1]
    else:
        pal_candidate = left + left[-2::-1]

    if int(pal_candidate) > n:
        return int(pal_candidate)

    # Increment the left half and form palindrome again
    left_num = int(left) + 1
    left = str(left_num)
    if len(left) > half:  # handle overflow like 999 + 1 = 1000
        if length % 2 == 0:
            pal_candidate = left + left[:-1][::-1]
        else:
            pal_candidate = left + left[-2::-1]
    else:
        if length % 2 == 0:
            pal_candidate = left + left[::-1]
        else:
            pal_candidate = left + left[-2::-1]

    return int(pal_candidate)

def common_in_nested_lists(nested_lists):
    if not nested_lists:
        return []
    common_set = set(nested_lists[0])
    for lst in nested_lists[1:]:
        common_set &= set(lst)
    return list(common_set)

def max_product_tuple(tuples):
    if not tuples:
        return 0
    max_product = None
    for t in tuples:
        if not t or len(t) < 2:
            continue
        for i in range(len(t)):
            for j in range(i+1, len(t)):
                product = t[i] * t[j]
                if max_product is None or product > max_product:
                    max_product = product
    return max_product if max_product is not None else 0

def amicable_numbers_sum(n):
    def sum_proper_divisors(x):
        s = 1
        i = 2
        while i * i <= x:
            if x % i == 0:
                s += i
                if i != x // i:
                    s += x // i
            i += 1
        return s if x > 1 else 0

    total = 0
    visited = set()
    for a in range(2, n + 1):
        if a not in visited:
            b = sum_proper_divisors(a)
            if b != a and b <= n:
                if sum_proper_divisors(b) == a:
                    total += a + b
                    visited.add(a)
                    visited.add(b)
    return total

def sum(a: int, b: int) -> int:
    from math import gcd
    g = gcd(a, b)
    total = 0
    i = 1
    while i * i <= g:
        if g % i == 0:
            total += i
            if i != g // i:
                total += g // i
        i += 1
    return total

def magic_square_test(matrix):
    n = len(matrix)
    if n == 0 or any(len(row) != n for row in matrix):
        return False
    # For n=1, any single number is a magic square
    if n == 1:
        return True
    # Calculate the magic sum from the first row
    magic_sum = sum(matrix[0])
    # Check rows
    for row in matrix:
        if sum(row) != magic_sum:
            return False
    # Check columns
    for c in range(n):
        if sum(matrix[r][c] for r in range(n)) != magic_sum:
            return False
    # Check main diagonal
    if sum(matrix[i][i] for i in range(n)) != magic_sum:
        return False
    # Check secondary diagonal
    if sum(matrix[i][n - 1 - i] for i in range(n)) != magic_sum:
        return False
    return True
